const input = $input.item.json || {};
const msg = input.message || {};

const rawText = String(msg.text || msg.caption || input.text || input.rawText || '').trim();
const document = msg.document || null;
const photo = Array.isArray(msg.photo) && msg.photo.length ? msg.photo[msg.photo.length - 1] : null;
const video = msg.video || null;
const audio = msg.audio || msg.voice || null;
const location = msg.location || null;
const contact = msg.contact || null;

let attachmentKind = 'none';
if (document) attachmentKind = 'document';
else if (photo) attachmentKind = 'photo';
else if (video) attachmentKind = 'video';
else if (audio) attachmentKind = 'audio';
else if (location) attachmentKind = 'location';
else if (contact) attachmentKind = 'contact';

const fileName = document?.file_name || video?.file_name || audio?.file_name || '';
const fileId = document?.file_id || video?.file_id || audio?.file_id || photo?.file_id || '';
const hasAttachment = attachmentKind !== 'none';

let effectiveText = rawText;
if (!effectiveText && hasAttachment) {
  if (attachmentKind === 'document' && fileName) {
    effectiveText = `Mình vừa gửi một file tên ${fileName}. Hãy hỏi lại mình cần làm gì với file này.`;
  } else {
    effectiveText = `Mình vừa gửi một ${attachmentKind}. Hãy hỏi lại mình muốn Mia làm gì tiếp theo.`;
  }
}

if (!effectiveText) {
  effectiveText = 'Xin chào Mia';
}

return [{
  json: {
    chatId: String(msg.chat?.id || ''),
    rawText: effectiveText,
    originalText: rawText,
    attachmentKind,
    hasAttachment,
    fileName,
    fileId,
    message: msg,
    payload: input
  }
}];

const source = $('Normalize Telegram Input').item.json || {};
const raw = String($json.final_text || $json.text || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
const text = raw || 'Xin lỗi, Mia chưa tạo được phản hồi. Bạn thử nói lại ngắn hơn giúp Mia nhé.';
return [{ json: { chatId: source.chatId, text, toolsCalled: $json.tools_called || [], threadId: $json.thread_id || '', requestId: $json.request_id || '' } }];
